/**
 * One invalid input. Exactly one of `pointer` and `parameter` is set.
 */
export const zProblemFieldError = z.object({
    pointer: z.string().nullable(),
    parameter: z.string().nullable(),
    code: z.enum([
        'REQUIRED',
        'UNKNOWN_FIELD',
        'INVALID'
    ]),
    detail: z.string()
});

/**
 * Problem details (RFC 9457), served as `application/problem+json`.
 * `code`, `traceId` and `errors` are Aether-os extensions. Clients switch
 * on `code`; `detail` is for people.
 *
 */
export const zCommonOpenapiProblem = z.object({
    type: z.string(),
    title: z.string(),
    status: z.int(),
    detail: z.string(),
    instance: z.string(),
    code: z.string(),
    traceId: z.string().nullable(),
    errors: z.array(zProblemFieldError)
});

export const zProblem = zCommonOpenapiProblem;

/**
 * Problem details for a business-rule violation.
 */
export const zDomainProblem = zCommonOpenapiProblem.and(z.object({
    code: zDomainErrorCode
}));

